const run = (args: string[]) => { const r = spawnSync("node", [CLI, ...args], { cwd: repo, env, encoding: "buffer", timeout: 120000 }); return Buffer.concat([r.stdout, Buffer.from("\n--stderr--\n"), r.stderr]); };
