process.env.HOME = path.join(base, "home"); fs.mkdirSync(process.env.HOME!);
const { inspectWorkspaceManifestPlugins } = await import("/home/mike/nexus-wt/rev808b/cli/src/core/workspace_plugins.js");
const ws = path.join(base, "ws"); fs.mkdirSync(ws); 
const mk = (name: string, body: string) => {
  const d = path.join(ws, ".nexus/plugins", name); fs.mkdirSync(d, { recursive: true });
  fs.writeFileSync(path.join(d, "nexus-plugin.json"), JSON.stringify({ version: 1, name, pluginVersion: "1.0.0", permissions: ["hooks"], contributions: { hooks: ["hooks.json"] } }));
  fs.writeFileSync(path.join(d, "hooks.json"), JSON.stringify({ version: 1, hooks: { "pre-tool": [{ name: "ok", tools: ["write_file"], command: ["./c.sh"] }] } }));
  fs.writeFileSync(path.join(d, "c.sh"), body, { mode: 0o755 }); return d;
};
const opts = { workspace: ws, readOnly: false, trusted: true, policy: () => ({}) as any, approvals: [] as any[] };
let stale = 0, N = 300, detected = 0;
for (let i = 0; i < N; i++) {
  const name = "p" + i; const d = mk(name, "#!/bin/sh\necho GOOD\n");
  const a = inspectWorkspaceManifestPlugins(opts).find((p) => p.name === name)!;   // reads A
  fs.writeFileSync(path.join(d, "c.sh"), "#!/bin/sh\necho EVIL\n", { mode: 0o755 });  // same size, same tick (maybe)
  const b = inspectWorkspaceManifestPlugins(opts).find((p) => p.name === name)!;
  const disk = fs.readFileSync(path.join(d, "c.sh"), "utf8").includes("EVIL");
  if (disk && a.digest === b.digest) stale++; else if (disk) detected++;
}
console.log(`inspect-after-write: stale cache served ${stale}/${N}, change detected ${detected}/${N}`);
console.log(base);
EOF
